"""Price lookup with per-instance caching.

Refactored away from a module-level singleton cache: each PriceCatalog
owns its own cache (fresh dict by default), so instances are isolated
and tests are order-independent.
"""


class PriceCatalog:
    def __init__(self, db, cache=None):
        self.db = db
        self.cache = {} if cache is None else cache

    def get_price(self, sku):
        if sku in self.cache:
            return self.cache[sku]
        row = self.db.execute(
            "SELECT cents FROM prices WHERE sku = ?", (sku,)
        ).fetchone()
        if row is None:
            # Deliberately NOT cached: an unknown SKU may be inserted later,
            # and caching negative results would poison the instance.
            raise KeyError(sku)
        self.cache[sku] = row[0]
        return row[0]

    def quote(self, skus):
        return sum(self.get_price(s) for s in skus)


_DEFAULT = None


def default_catalog():
    """Return the process-wide default catalog.

    Tests should call reset_default_catalog() in setup to avoid leakage.
    """
    global _DEFAULT
    if _DEFAULT is None:
        from pricing_db import get_db  # optional lazy hook

        _DEFAULT = PriceCatalog(get_db())
    return _DEFAULT


def reset_default_catalog(db=None):
    """Reset the default catalog; optionally seed it with a specific db."""
    global _DEFAULT
    _DEFAULT = None if db is None else PriceCatalog(db)


def get_price(sku, db):
    return default_catalog_with_db(db).get_price(sku)


def quote(skus, db):
    return default_catalog_with_db(db).quote(skus)


def default_catalog_with_db(db):
    """Backward-compatible wrapper target: a default catalog bound to db."""
    global _DEFAULT
    if _DEFAULT is None:
        _DEFAULT = PriceCatalog(db)
    return _DEFAULT

