class CountingDb:
    """Wraps a sqlite3 connection; every execute() goes through the spy."""

    def __init__(self, conn):
        self._conn = conn
        self.counts = {"selects": 0}

    def execute(self, sql, params=()):
        # lazily delegate so the counting cursor actually observes the call
        return CountingCursor(self._conn, self.counts).execute(sql, params)

